//
// Human-readable formatting of sizes, rates and durations. All output is
// generated by this original implementation (SI-style binary prefixes).
#pragma once

#include <cstdint>
#include <string>

namespace sysograph {

// 1536 -> "1.5 KiB"; keeps at least one decimal below 100.
std::string formatBytes(uint64_t bytes);

// 1536 -> "1.5 KiB/s"
std::string formatBytesPerSecond(double bytes_per_second);

// 12.34 -> "12.3 %"
std::string formatPercent(double percent);

// 3725 -> "1:02:05" (h:mm:ss); >24h -> "2d 1:02:05"
std::string formatDurationHMS(double seconds);

// 86400*3 -> "3d 0h"; minutes granularity, for uptimes.
std::string formatUptime(double seconds);

// 42 -> "42"; formatting of plain counts with no trailing ".0".
std::string formatCount(double value);

}  // namespace sysograph
